import { useEffect, useState } from 'react';

// Tiruan server: menunggu 800 ms, lalu mengembalikan data atau gagal.
function ambilProduk(gagal) {
  return new Promise((berhasil, tolak) => {
    setTimeout(() => {
      if (gagal) tolak(new Error('Server menjawab 500'));
      else berhasil([
        { id: 1, nama: 'Kopi Susu' },
        { id: 2, nama: 'Teh Melati' },
        { id: 3, nama: 'Roti Bakar' },
      ]);
    }, 800);
  });
}

export default function App() {
  const [produk, setProduk] = useState([]);
  const [loading, setLoading] = useState(true);
  const [galat, setGalat] = useState('');
  const [percobaan, setPercobaan] = useState({ ke: 1, gagal: false });

  useEffect(() => {
    let batal = false;
    async function ambil() {
      try {
        setLoading(true);
        setGalat('');
        const hasil = await ambilProduk(percobaan.gagal);
        if (!batal) setProduk(hasil);
      } catch (e) {
        if (!batal) setGalat(e.message);
      } finally {
        if (!batal) setLoading(false);
      }
    }
    ambil();
    return () => { batal = true; };
  }, [percobaan]);

  let isi;
  if (loading) isi = <p>Memuat produk...</p>;
  else if (galat) isi = <p role="alert">Gagal memuat: {galat}</p>;
  else isi = <ul>{produk.map((p) => <li key={p.id}>{p.nama}</li>)}</ul>;

  return (
    <div>
      {isi}
      <button onClick={() => setPercobaan({ ke: percobaan.ke + 1, gagal: true })}>Coba lagi (gagal)</button>{' '}
      <button onClick={() => setPercobaan({ ke: percobaan.ke + 1, gagal: false })}>Coba lagi (berhasil)</button>
    </div>
  );
}
